/* Reference-image reverse prompting: analysis first, then the learner's own product. No AI calls or uploads. */
(()=>{'use strict';const api=window.CourseState,studio=window.CourseStudio,$=id=>document.getElementById(id),stage=$('stage11');if(!api||!studio||!stage||$('reverseLesson'))return;
const title='逆生成技巧（額外分享）',fields={reverseProduct:'自己的商品與特色',reverseUse:'圖像用途',reverseBorrow:'參考圖想借用的面向',reverseKeep:'必須保留的商品與人物設定',reverseSize:'圖片尺寸或比例',reverseCopy:'核定圖內文案',reverseAnalysis:'貼回AI的參考圖拆解結果'};
const aspects=[['主體與人物','商品種類、數量、人物姿態與接觸位置'],['場景與道具','背景環境、擺放方式、必要陪襯'],['構圖與版位','主角位置、大小、留白與閱讀順序'],['視角與取景','正面或斜側、平視或俯視、完整商品或局部'],['燈光與陰影','可見光向、柔硬程度、明暗與接觸陰影'],['配色與質感','背景色、點綴色、可見材質與表面細節'],['畫風與文字','攝影／插畫方向、文字層級與字體大類'],['比例與限制','估計畫面比例、無法確認的規格與資訊']];
const previous=document.createElement('details');previous.className='reverse-previous';previous.id='portraitExtension';previous.innerHTML='<summary>延伸教學｜如何避免人像 AI 感（點開查看）</summary>';for(const el of [...stage.children])if(el.classList.contains('portrait-block')||el.id==='portraitStatus')previous.append(el);stage.append(previous);
stage.querySelector('h2').textContent='11 '+title;stage.querySelector('.lead').textContent='上傳參考圖 → 拆解畫面設定 → 換成自己的產品 → 生成新圖。';const nav=$('portraitNav');nav.querySelector('span').textContent='11 '+title;nav.querySelector('small').textContent='看圖拆解、替換產品、生成自己的作品';
const root=document.createElement('div');root.id='reverseLesson';root.innerHTML='<section class="reverse-block"><h3>逆生成，是從畫面推估提示詞</h3><p>先請 AI 說明參考圖如何安排主體、構圖、燈光與配色，再把這些視覺方法用在自己的產品上。</p><p class="reverse-note"><strong>AI 無法從圖片還原原作者的原始 Prompt。</strong>可以拆解的是看得見的內容與合理推估；實際材質、商品規格、精確字型及攝影參數，仍須另外確認。</p><div class="reverse-flow"><article><b>01</b><strong>附上參考圖</strong><p>在 AI 工具上傳想分析的畫面，說明想參考哪些面向。</p></article><article><b>02</b><strong>拆解畫面</strong><p>先看分析與推估，不急著生成；選出適合沿用的方法。</p></article><article><b>03</b><strong>換自己的產品</strong><p>附上自家商品照，填入要保留的特色與核定文案。</p></article><article><b>04</b><strong>直接生成新圖</strong><p>使用第二段指令產圖，再核對商品與人物的細節。</p></article></div><p class="reverse-small">參考圖與商品圖請在 AI 工具另外上傳。本網站提供教學、提示詞與本機保存，不會自動讀圖或把照片傳給 AI。</p></section><section class="reverse-block"><h3>1. 上傳參考圖，請 AI 拆解</h3><p>可把參考圖標成「圖 A」，接著貼上這段提示詞。</p><details><summary>可以拆解哪些面向？</summary><div class="reverse-table"><table><thead><tr><th>面向</th><th>觀察重點</th></tr></thead><tbody>'+aspects.map(([a,b])=>'<tr><td>'+a+'</td><td>'+b+'</td></tr>').join('')+'</tbody></table></div></details><label for="reverseAnalyzePrompt">參考圖拆解提示詞<textarea id="reverseAnalyzePrompt" rows="12" readonly></textarea></label><button class="primary" type="button" data-reverse-copy="analyze">複製拆解提示詞</button></section><section class="reverse-block"><h3>2. 換成自己的商品與用途</h3><p>接續同一段 AI 對話。將自己的商品照標成「圖 B」，作為產品外型與配色的依據；只補這次需要調整的項目。</p><label for="reverseProduct">自己的商品與特色<input id="reverseProduct" maxlength="8000" placeholder="例如：TUMAZ 瑜珈磚；材質、配色與外型依附上的商品照"></label><label for="reverseUse">圖像用途<input id="reverseUse" maxlength="3000" placeholder="例如：電商商品介紹、社群貼文、生活情境；可留白沿用"></label><label for="reverseBorrow">參考圖想借用的面向<input id="reverseBorrow" maxlength="8000" placeholder="例如：只參考構圖與燈光；配色依自己的品牌"></label><div class="reverse-presets"><button type="button" data-reverse-borrow="構圖與留白">構圖與留白</button><button type="button" data-reverse-borrow="燈光與陰影">燈光與陰影</button><button type="button" data-reverse-borrow="背景配色與畫風">背景配色與畫風</button><button type="button" data-reverse-borrow="整體視覺方向，重新安排人物、商品與文案">整體視覺方向</button></div><label for="reverseKeep">必須保留的商品與人物設定<textarea id="reverseKeep" rows="3" maxlength="20000" placeholder="例如：商品原色、圖紋、斜切邊、合理尺寸；人物依自己的設定"></textarea></label><label for="reverseSize">圖片尺寸或比例<input id="reverseSize" maxlength="3000" placeholder="例如：1080 × 1350 px、4:5；未定可請 AI 建議"></label><label for="reverseCopy">核定圖內文案<textarea id="reverseCopy" rows="3" maxlength="30000" placeholder="填入主標與短文案；留白時不加入版面文字，預留文案空間"></textarea></label><button type="button" id="reverseCarryCopy">帶入目前核定圖內文案</button><label for="reverseAnalysis">貼回 AI 的參考圖拆解結果（選填）<textarea id="reverseAnalysis" rows="5" maxlength="300000" placeholder="同一段 AI 對話已有分析可留白沿用；換新對話時，可貼上拆解結果。"></textarea></label></section><section class="reverse-block"><h3>3. 生成自己的產品圖像</h3><p>將這段貼回同一段 AI 對話，並附上自己的商品圖。這一步會要求 AI 直接生成新圖。</p><label for="reverseGeneratePrompt">自己的商品生成指令<textarea id="reverseGeneratePrompt" rows="14" readonly></textarea></label><div class="actions"><button class="primary" type="button" data-reverse-copy="generate">複製自身商品生成指令</button><button type="button" id="reverseDownload">下載兩段提示詞 TXT</button></div></section><section class="reverse-block"><h3>範例｜參考構圖，換成自己的瑜珈磚</h3><p><strong>參考圖 A：</strong>人物在右側介紹商品，左側留有標題空間，使用柔和側前方光。</p><p><strong>自己的商品圖 B：</strong>TUMAZ 瑜珈磚。請依商品照保留外型、原色與圖紋，不沿用參考圖的商品、標誌或人物身分。</p><p><strong>生成方向：</strong>人物自然承托瑜珈磚，商品清楚完整，左側保留文字區。圖內文案可改為「TUMAZ 瑜珈磚｜為日常練習準備輔具」。用途與操作方式仍依已確認資料。</p><p class="reverse-note">選擇有權使用的參考素材。學習構圖、光線與配色的方法，重新安排自己的產品、人物、背景與文案。</p><h4>生成後，核對這三件事</h4><ul><li>參考圖的視覺方法是否有被正確運用？</li><li>自己的商品是否仍符合原照，沒有多出配件、圖紋或功能？</li><li>人物、手部接觸、文字與版面是否清楚合理？</li></ul></section><p id="reverseStatus" role="status" aria-live="polite"></p>';
stage.insertBefore(root,previous);
function analyze(v=api.get()){return ['請分析我上傳的參考圖（圖 A），拆解可觀察的畫面設定，推估適合描述這種視覺方向的提示詞。這是看圖分析，不是還原原作者的原始 Prompt。','【本次想參考的面向】\n'+(v.reverseBorrow?.trim()||'先完整拆解，再指出哪些面向適合運用在自己的產品上。'),'請用表格整理：主體與人物、動作與接觸、場景與道具、構圖與留白、視角與取景、燈光與陰影、配色與材質、畫風、文字與版位、畫面比例。每一項分清楚「圖中可見細節」「合理推估」「無法確認」。','只描述看得見的材質特徵，不把觀感當成商品規格或性能。字型可描述大類、粗細與字距，不確定時不要聲稱精確字型；焦段、光圈、拍攝器材與不可見結構也不要憑空填寫。','接著提供：\n1. 一份參考圖的完整視覺描述，方便我理解畫面。\n2. 可沿用的構圖、燈光或配色方法。\n3. 換成自己產品時應替換的商品、人物、品牌、文案與場景元素。','若看不到附圖，請直接告訴我補上參考圖，不要假裝已分析。本輪先完成拆解與視覺描述，不生成圖片。'].join('\n\n');}
function generate(v=api.get()){const product=v.reverseProduct?.trim()||v.topic?.trim()||'沿用已確認的自家產品，外型與配色依我附上的商品圖（圖 B）',copy=v.reverseCopy?.trim();return ['請接續前面的參考圖拆解，把選定的視覺方法用在我的產品上，直接生成 1 張新圖。','【兩種參考圖的用途】\n圖 A 是視覺方向參考；圖 B 是我的商品外觀依據。人物若另有參考，請依我明確提供的設定處理。沒有附上圖像時，先告訴我缺少哪張，不冒稱已讀取。','【自己的產品與任務】\n商品：'+product+'\n用途：'+(v.reverseUse?.trim()||'沿用目前的商品介紹用途')+'\n尺寸與比例：'+(v.reverseSize?.trim()||v.lessonSize||'請依用途建議合適的畫面比例，說明採用的設計尺寸'),'【參考圖想借用的面向】\n'+(v.reverseBorrow?.trim()||'採用適合本次產品的構圖、留白與光線方法；其餘元素依自己的品牌與產品重新安排。'),'【已完成的拆解】\n'+(v.reverseAnalysis?.trim()||'沿用同一段對話中已完成的圖 A 拆解。若尚未分析，先簡述可觀察的畫面設定，再依本次產品直接生成。'),'【保留自己的產品】\n'+(v.reverseKeep?.trim()||'依商品照保留外型、原色、材質、圖紋、數量與合理比例。')+'\n不把圖 A 的商品、商標、人物身分或原文案當成我的設定。背景、人物與文案依本次產品重做，不直接複製整張參考畫面。只依已確認用途安排動作，手指與產品接觸、受力與陰影須合理。','【圖內文字】\n'+(copy?'逐字使用以下核定文案，文字清楚，不遮住臉、手或商品：\n'+copy:'本次不增加版面文字，預留乾淨文案空間；商品本身已有的標示依參考照保留。'),'不補造材質規格、功效、價格、優惠或配件；資料不足另列待確認。請直接生成圖片，不只提供新的 Prompt。若工具無法產圖，請明說，不把未生成的圖像當成已完成。'].join('\n\n');}
function header(){if(stage.hidden||location.hash!=='#stage11')return;$('where').textContent='目前所在：11 '+title;$('stageLabel').textContent='額外分享｜逆生成';$('progress').textContent='先拆解參考圖，再生成自己的作品';}
function refresh(){const v=api.get();for(const k of Object.keys(fields))if($(k).value!==(v[k]||''))$(k).value=v[k]||'';$('reverseAnalyzePrompt').value=analyze(v);$('reverseGeneratePrompt').value=generate(v);header();}
const oldRefresh=studio.refresh,oldLabels=studio.labels,oldExport=studio.exportPrompts;studio.refresh=function(v){if(location.hash!=='#stage11'&&([...Array(10)].some((_,i)=>!$('stage'+(i+1)).hidden)||!$('resultsPanel').hidden))stage.hidden=true;oldRefresh(v);refresh();};studio.labels=()=>({...oldLabels(),...Object.fromEntries(Object.entries(fields).map(([k,t])=>[k,'11 逆生成｜'+t]))});studio.exportPrompts=v=>{const out=oldExport(v);if(Object.keys(fields).some(k=>v[k]?.trim()))out.push({stage:'11 額外分享｜逆生成：拆解與自己的商品生成',text:analyze(v)+'\n\n──────────\n\n'+generate(v)});return out;};
const oldShow=api.show;api.show=function(n,scroll=true){oldShow(n,scroll);header();};const oldClick=nav.onclick;nav.onclick=function(e){oldClick.call(this,e);header();};if(window.CoursePortrait){const show=window.CoursePortrait.show;window.CoursePortrait.show=function(...args){show(...args);header();};}window.addEventListener('hashchange',header);
root.addEventListener('input',e=>{if(Object.hasOwn(fields,e.target.id))api.set(e.target.id,e.target.value);});root.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.reverseBorrow){api.set('reverseBorrow',b.dataset.reverseBorrow);$('reverseStatus').textContent='已選用參考面向，兩段提示詞已更新。';}if(b.id==='reverseCarryCopy'){const v=api.get(),s=v.lessonCopy||v.onImageFinal||'';if(s){api.set('reverseCopy',s);$('reverseStatus').textContent='已帶入目前核定圖內文案，請確認仍適合這次用途。';}else $('reverseStatus').textContent='目前沒有已確認的圖內文案，可自行填寫或使用無字留白版。';}if(b.dataset.reverseCopy){const text=b.dataset.reverseCopy==='analyze'?analyze():generate();try{await navigator.clipboard.writeText(text);$('reverseStatus').textContent=b.dataset.reverseCopy==='analyze'?'已複製。先在 AI 工具附上參考圖 A，再貼上進行拆解。':'已複製。請在同一段 AI 對話附上自己的商品圖 B，再貼上生成新圖。';}catch{$('reverseStatus').textContent='瀏覽器未允許複製，請選取提示詞手動複製，或下載 TXT。';}}if(b.id==='reverseDownload')api.download('逆生成_拆解與自己的產品生成.txt','【第一步：參考圖拆解】\n'+analyze()+'\n\n【第二步：自己的商品生成】\n'+generate(),'text/plain;charset=utf-8');});
const css=document.createElement('style');css.textContent='.reverse-block{margin:22px 0;padding:22px;border:1px solid #ded8f1;border-radius:16px;background:white}.reverse-block h3{margin-top:0}.reverse-block p,.reverse-block li{line-height:1.85}.reverse-block label{display:block;font-weight:600;margin:16px 0}.reverse-block input,.reverse-block textarea{box-sizing:border-box;display:block;width:100%;max-width:100%;margin-top:8px;padding:12px;border:1px solid #d3cbed;border-radius:10px;color:#333366;background:white;font:inherit;line-height:1.7}.reverse-block textarea[readonly]{background:#faf9fe}.reverse-note{padding:16px;background:#f4f1ff;border-radius:10px}.reverse-small{font-size:14px}.reverse-flow{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:20px 0}.reverse-flow article{padding:16px;background:#f7f5ff;border-radius:12px;min-width:0}.reverse-flow b{display:block;font-size:24px;color:#6651d9;margin-bottom:8px}.reverse-flow strong{display:block}.reverse-flow p{font-size:14px;margin-bottom:0}.reverse-table{overflow-x:auto}.reverse-table table{width:100%;min-width:420px;border-collapse:collapse;margin:16px 0}.reverse-table td,.reverse-table th{text-align:left;padding:12px;border-bottom:1px solid #e2dced;vertical-align:top}.reverse-table th{background:#f3efff}.reverse-presets{display:flex;gap:8px;flex-wrap:wrap}.reverse-block button{min-height:44px}.reverse-previous{padding:18px;border:1px solid #d9d1ee;border-radius:14px;margin:24px 0}.reverse-previous>summary{font-size:18px;font-weight:600;color:#5945bd;cursor:pointer}#reverseStatus{color:#5742ae;line-height:1.8}@media(max-width:800px){.reverse-flow{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:500px){.reverse-flow{grid-template-columns:1fr}.reverse-block{padding:16px}.reverse-block input,.reverse-block textarea{font-size:16px}.reverse-previous{padding:12px}}';document.head.append(css);refresh();window.CourseReverse={analyze,generate,refresh};window.WorkshopResults.refresh();document.documentElement.dataset.courseReverse='20261120';
})();

